INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1002, 'BUY1TAKE1 NIACINAMIDE TAWAS SOAP WITH FREE MESH 100g', 'Pakilala natin ang FDA approved Niacinamide Tawas Soap 100g with Mesh! Ito ay isang sabon na mayaman sa Niacinamide at Pottasium alum na may kakayahan sa pagpapabuti ng kalagayan ng iyong balat. Ang Niacinamide ay kilala bilang isang sangkap na nagbibigay ng maraming benepisyo para sa malusog at maganda ang kalagayan ng balat. Ito ay nakakatulong upang mapabuti ang pigmentation, wrinkles, at kung paano tayo magmukhang mas bata. Hindi lang iyon, nakakapagpatibay din ito ng natural moisture barrier upang siguraduhing mas bumabata tayo kahit matagal narin. Ang Pottasium alum naman ay kilalang mabisang deodorant at natural antiperspirant dahil ito ay nagpapatuyo sa amoy kasabay pa rin nitong pagiging hypoallergenic. Ang FDA approved Niacinamide Tawas Soap 100g with Mesh ay ginawa para maprotektahan ka laban sa mga alerdyi. Maliban pa rito, ito rin ay ginawa upng matiyak ang pormalisadong pamamaraan galing FDA bago makalabas ito market. Hindi mo pwedeng palampasin siya! Mag-order ka na!', 'Beauty & Personal Care', 'Naicinamide Tawas Soap', 135.0, 56, '["https://down-ph.img.susercontent.com/file/ph-11134207-7r98u-ly66qqh047paec_tn","https://down-ph.img.susercontent.com/file/ph-11134207-7r98q-ly66qqh05m9q76_tn","https://down-ph.img.susercontent.com/file/ph-11134207-7r98p-ly66qqh047ei47_tn","https://down-ph.img.susercontent.com/file/ph-11134207-7r98r-ly66qqi42l8e84_tn","https://down-ph.img.susercontent.com/file/ph-11134207-7r98q-ly66qqi43zi289_tn","https://down-ph.img.susercontent.com/file/ph-11134207-7r98y-ly66qqi42kxmfd_tn"]', 5.0, 1, 16);
INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1003, 'El Gaitero Gaitero "Spanish Cider" 100% Apple, 12 x 330 ml', 'In this way and by making a correct mixture of the different apple groups, taking into account their organoleptic and technological characteristics (sweet, bitter and acidic), we obtain a high quality must for, after a slow alcoholic fermentation and at low temperatures, to make natural cider . The process is completed with clarification, filtration, sweetening and carbonation resulting in an extra semi-dry cider. It Gluten free. Colour: Clear yellow with lots of well-integrated bubbles. Smell: Complex and structured, with a bouquet of ripe fruit. Taste: An excellent balance of acidity and sweetness, making for an elegantly lingering finish.', 'Food & Grocery', 'El Gaitero', 94.8, 79, '["https://down-sg.img.susercontent.com/file/sg-11134301-7rd3y-lwpdhghjmd0g5c_tn","https://down-sg.img.susercontent.com/file/sg-11134301-7rd4c-lwpdk5d9uhjg09_tn","https://down-sg.img.susercontent.com/file/sg-11134301-7rd42-lwpdk5dtto67b9_tn"]', 5.0, 1, 44);
