INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1093, 'Zuke''s Mini Naturals Soft Dog Training Treats, Duck Flavor, Tender Dog Chew Snacks, 16 oz Pouch', 'Live life off leash with Zuke''s Mini Naturals Duck Recipe soft treats for dogs. Mini Naturals healthy dog treats allow you to offer your dog training treats with guilt-free confidence. These natural dog treats contain real duck as the first ingredient, with whole foods like cherries to offer your dog soft treats packed with natures simple, delicious flavors. Crafted using the Earths best ingredients, these duck treats for dogs contain no corn, wheat, or soy. With only 2 calories in each of these purposefully small dog treats, Zukes Mini Naturals duck dog treats are the perfect healthy dog treats for training or rewarding your dog on adventures. Zukes training treats for dogs are ideal doggy treats for pups of all sizes, offering soft chewy dog treats for large dogs, medium dogs, and small dogs in a single-sized, soft dog treats recipe. Every pouch of Zukes Mini Naturals dog treats reseals for easy, on-the-go rewards, so any journey can be an off-leash adventure.', 'Home & Living', 'Zuke''s', 16.7, 70, '"https://i5.walmartimages.com/seo/Zukes-Mini-Naturals-Duck-Recipe-Dog-Training-Treats_6872ec6d-19f1-4449-944f-4aa5b163bd9b.4977c122ea4f9a9ff597f4c899ba51d8.jpeg"', 4.0, 3, 35);
