INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1095, 'Reebok Boys Power Blast Muscle Active Tank, Sizes 4-18', 'Reebok Boys'' sleeveless athleisure performance muscle tee, engineered for both style and functionality. Crafted entirely from high-quality 100% polyester, this tank top offers unparalleled comfort during active pursuits. The side panel and back yoke, made from compression mesh polyester and spandex, ensure optimal breathability and flexibility, allowing unrestricted movement. This muscle tee strikes the perfect balance between performance and trendiness, making it an essential addition to any active child''s wardrobe.', 'Home & Living', 'Reebok', 6.13, 67, '"https://i5.walmartimages.com/seo/Reebok-Boys-Power-Blast-Muscle-Active-Tank-Sizes-4-18_db8f6517-430b-451e-9005-4a4576f3a213.7a2d144e94a1eeab5c2914ac6dd3af33.jpeg"', 4.33, 3, 48);
INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1096, 'Russell Athletic Mens Lux Tech Fleece Pants, Sizes S-XL', 'Get ready to experience comfort and style with the Russell Athletic Lux Tech Fleece Athletic Fit Pants for Men. Crafted in the softest Lux Poly Tech fleece, these pants feature an athletic fit to ensure they move with you while providing maximum flexibility and comfort during every activity. With convenient zipper pockets, you can keep your essentials close by and within reach. The drawcord ensures a secure fit, so you can focus on your workout without any distractions.', 'Fashion', 'Russell Athletic', 16.0, 67, '"https://i5.walmartimages.com/seo/Russell-Athletic-Men-s-Lux-Tech-Fleece-Pants-Sizes-S-XL_658967f0-51e1-4534-bd85-d59d0a8311b9.b90a54788aa69601bd43e1aa4454ed17.jpeg"', 0.0, 0, 5);
INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1097, 'Hanes Men''s and Big Men''s Beefy Tee with Short Sleeves, 2-Pack, Sizes S-6XL', 'For guys who need a little more room and a little more length, Hanes has you covered with this quality tee from the Tall Beefy-T collection. 3&quot; longer with a roomier, more generous fit, this classic cotton tee for men is exactly what you need for easy comfort. Made of ring-spun cotton, this crewneck T-shirt for men is soft and effortless. Quality details are built into this sturdy cotton tee, from the ribbed, lay-flat crewneck to the sturdy double-needle stitching at the sleeves and hem to the no-chafe reinforcing shoulder-to-shoulder inside taping. Stock up on this extra long tee for men from Hanes in a convenient value pack of 2 tees.', 'Home & Living', 'Hanes', 14.6, 82, '"https://i5.walmartimages.com/seo/Hanes-Men-s-and-Big-Men-s-Beefy-Tee-with-Short-Sleeves-2-Pack-Sizes-S-6XL_f860b6c6-58c3-4153-9766-5c364e787838_1.f4591f8d732b2954c0ddd22c6769df37.jpeg"', 3.0, 1, 39);
