INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1100, 'RAW X Toddler Boy''s RawX Rip and Repair Jeans, Dark Blue, 2T', 'Introducing the Raw X Boys Stretch Denim Jeans, a stylish and edgy addition to any young wardrobe. These jeans feature a modern design with moto biker-inspired elements and expertly crafted ripped details, adding a touch of rugged charm. Made from high-quality stretch denim, they ensure a comfortable fit and flexibility for all-day wear. Perfect for kids who love to combine fashion with comfort, the Raw X Boys Stretch Denim Jeans are a must-have for any trendsetting youngster.', 'Home & Living', 'RAW X', 18.5, 85, '"https://i5.walmartimages.com/seo/RAW-X-Boy-s-Skinny-Fit-Stretch-Jeans-Fashion-Rips-Destroyed-Distressed-Washed-Denim-Jean-Pants-for-Boys-Dark-Blue-99013-2T_d6160100-af48-4dd1-a86d-610ec60b8505.1607f1074ef2b172a4c6629b5c990845.jpeg"', 0.0, 0, 6);
