INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1255, 'Little Debbie Nutty Bars Ice Cream Bars, 12 fl oz, 4 Count', 'Snack time is forever changed! Family-owned brands Hudsonville Ice Cream and Little Debbie are collaborating again to put a cold and creamy twist on classic snack cakes, this time with seven new ice cream flavors! Experience the joy of Little Debbie Nutty Bar Ice Cream Bars. Indulge in the rich, peanut butter flavored ice cream, punctuated with delightful crispy milk chocolate pieces, all packed into four delicious three fluid ounce ice cream bars. Crafted with care since 1926, delight in each spoonful that promises happiness without the worry of common allergens. With a careful selection of ingredients to ensure the highest quality and tastiest ice cream, Little Debbie ice cream makes celebrations easy and delicious.', 'Home & Living', 'Little Debbie', 3.97, 56, '"https://i5.walmartimages.com/seo/Little-Debbie-Nutty-Bars-Ice-Cream-Bars-12-fl-oz-4-Count_3df62825-d210-4361-af23-970a00157677.5ad18ab5e534b930e9f9b47f798bb943.png"', 0.0, 0, 16);
INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1256, 'Made by Johnny Women''s Short Sleeve All Over Tie-Dye Tunic Top L BROWN', 'This stunning women''s short sleeve asymmetrical tunic top is the perfect addition to any wardrobe. Crafted from lightweight, breathable fabric (95% Rayon / 5% Spandex), this top is designed to flatter the figure in all the right places. The short sleeves and asymmetrical hemline give this top a contemporary feel, while the classic cut ensures it can be worn for a variety of occasions. The loose-fitting silhouette is comfortable and relaxed, making it a great choice for casual or formal events. The versatile design allows for a variety of styling options, making it ideal for pairing with jeans and flats for an effortless weekend look, or with tailored trousers and heels for an evening out. With beautiful detailing, such as an eye-catching neckline and delicate buttons, this top is the perfect way to look put-together and chic.', 'Home & Living', 'Made by Johnny', 15.0, 33, '"https://i5.walmartimages.com/seo/Made-by-Johnny-Women-s-Short-Sleeve-All-Over-Tie-Dye-Tunic-Top-L-BROWN_339aaf67-16df-4949-b436-5442393d9acd.275413e9c2d0e844e0bd0be88703e622.jpeg"', 0.0, 0, 5);
