INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1267, 'Organic Maqui Berry Powder, 2 Pounds Non-GMO, Raw, Vegan by Food to Live', 'Organic Maqui Berry Powder has recently joined popular antioxidant superfood lists. This powder is packed with vitamins, including vitamin C, as well as fiber and various antioxidants. Its easy to include in your diet and it can help boost the flavor of smoothies and oatmeal. Organic Maqui Powder by Food to Live retains as many of the nutrients as possible. Its all thanks to the processing method used to minimize the destruction of temperature-sensitive antioxidant compounds. The very fine maqui fruit powder is easy to mix into various dishes. Start with teaspoon of powder a day and increase the dosage based on how you react to it. You can enjoy Organic Maqui Berry Powder by adding a teaspoon of it to your glass of morning juice.', 'Home & Living', 'Food to Live', 112.0, 78, '"https://i5.walmartimages.com/seo/Organic-Maqui-Berry-Powder-2-Pounds-Non-GMO-Raw-Vegan-by-Food-to-Live_3a42ff25-6455-40d7-a885-fa0fa476d89d.9ad1064836ff36d025edd2edf6670cec.jpeg"', 0.0, 0, 36);
