INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1273, 'Aiyino Women''s V Neck Floral Spaghetti Strap Summer Casual Swing Dress with Pocket', 'Material: Sleeveless wedding guest dress: 64% Viscose, 31% Ployester, 5% Elastane, silky, lightweight and very curvy, top lined, not see through, fits like a glove. Features: One-shoulder, sleeveless, high waist, off the shoulder, asymmetrical slit hem, ruched wrap design, formal dress, midi belted dress, cocktail party dress, holiday dress, wedding guest dress. Match: You can dress it up with high heels, sparkling jewelries, handbags for formal occasions. Wear it alone in spring and summer, and coat and jacket would be the ideal match in fall and winter. Size Attention: S=US 4-6, M=US 8-10L=US 12-14XL=US 16-18, 2XL=US 20-22. The ruched front design can hide your belly fat and make you look slimmer. Occasions: Wedding guest, cocktial party, holiday, formal, evening out, dancing, dinner, casual wear. Style good for spring, summer, autumn and winter.', 'Home & Living', 'Aiyino', 15.0, 49, '"https://i5.walmartimages.com/seo/Aiyino-Women-s-V-Neck-Floral-Spaghetti-Strap-Summer-Casual-Swing-Dress-with-Pocket_a0c46f04-cb6a-46f4-8626-b8224108c127.df701ae6875ee214df5e2edf1ccc7513.jpeg"', 0.0, 0, 43);
