INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1347, '(2 pack) Native Deodorant, Coconut & Vanilla, Aluminum Free, for Women and Men, 2.65 oz', 'If you are planning to switch to an aluminum-free deodorant, then try Native Deodorant with over 15,000 5-Star Reviews. Native deodorant is aluminum-free and contains naturally derived ingredients, with effective long-lasting odor protection. We believe you should not have to choose between a deodorant that makes you feel safe and a deodorant that works. We never use aluminum, parabens, or sulfates in any of our products. At Native we use both safe, synthetic, sustainable fragrances (free of phthalates) and natural fragrances. Native: Clean. Simple. Effective.', 'Home & Living', 'Native', 25.9, 29, '"https://i5.walmartimages.com/seo/Native-Deodorant-Coconut-Vanilla-Aluminum-Free-for-Women-and-Men-2-65-oz_6e3d7a71-b435-4dad-bcd6-0f9ddc83e4b0.333ac63041a9e62f6e83201b0025b9ae.jpeg"', 4.0, 1, 26);
