INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1349, 'Boulder Creek By Kingsize Men''s Big & Tall Western Snap Front Shirt', 'Boulder Creek By Kingsize Men''s Big &amp; Tall Western Snap Front Shirt .Get your denim ready for this western-style favorite. This lightweight Boulder Creek&reg; Western Shirt is sure to keep you comfortable with a large color variety to choose from.&nbsp; Relaxed fitBack yokeCream pearlized snaps&nbsp;Shirttail hemTagless labelCotton twill or denimMachine wash; imported&nbsp; Big length abt. 30&quot;Tall length abt. 32&quot;. About the brand: Boulder Creek is prepared for all of the big &amp; tall guys adventures. Whether its adding a side-elastic waist to our durable cotton twill cargos or adding extra pockets to our jackets, we make sure everything passes the test for reliability, utility, and comfort. Even if your adventures arent in the great outdoors, tackle life in gear thats rugged to the core.', 'Home & Living', 'Boulder Creek', 41.2, 35, '"https://i5.walmartimages.com/seo/Boulder-Creek-By-Kingsize-Men-s-Big-Tall-Western-Snap-Front-Shirt_d03c9972-9344-44ce-bf65-a8b9e3763e63.c46249eac25d8a0b4ecf527ea79033b1.jpeg"', 0.0, 0, 35);
