INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1355, 'Rugking Runner Rug 2x12 Vintage Printed Grey Area Rug Stairway Carpet Home Accent Thin Rug For Hallway Bedroom Kitchen Living Room', 'Click Here for Washable Bohemian Rugs Click Here for Modern style rugs Click Here for Modern Geometric Accent Rug Timeless design for every room: The RUGKING carpet uses traditional circular relief patterns, intricate crew designs and Persian-style details. It is the perfect complement to any modern-style room. Infinite Decoration: Decorate your bedroom, living room, dining room, study or entrance with this breathtaking decoration essential. Perfect for any indoor space! Low maintenance: Your polypropylene carpet is very easy to clean and maintain! You only need to vacuum regularly. Minimize effort to maximize beauty! Use non-slip bottom pads. High quality and durability: a unique combination of fashion, functionality and design. High-quality structural design brings long-lasting beauty. Anti-staining, anti-fading and anti-wear. Sizes suitable for various spaces: Our range includes various sizes to ensure that you choose carpets, rugs, runners and round rugs that meet your needs.', 'Home & Living', 'RUGKING', 42.4, 40, '"https://i5.walmartimages.com/seo/Rugking-Runner-Rug-2x12-Vintage-Printed-Grey-Area-Rug-Stairway-Carpet-Home-Accent-Thin-Rug-For-Hallway-Bedroom-Kitchen-Living-Room_c470fd5f-cb87-4446-b464-80b3e775c517.d7473d67b6bcceb4e07697e8f9e48d05.jpeg"', 5.0, 1, 4);
