INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1357, 'Redmond Earth Paste Natural Toothpaste, Unsweetend Spearmint, 4 Oz', 'It''s official - You''re a MUD MouthAmazingly Natural ToothpasteUnsweetened Extra StrongNo GlycerinNo FluorideFrom the EarthNo Artificial coloringNo Foaming AgentsDear FriendsYou may ask, why the name, Earthpaste? It''s a simple answer, really. All the ingredients in Earthpaste are from the earth. Earthpaste won''t be what you are used to because it is completely natural with very few ingredients. We don''t add titanium dioxide to make it white, nor do we add any foaming agents. Earthpaste is natural in color - it''s how toothpaste should be. We keep it real. Directions Wet brush before applying. For best flow, stand tube upright. Free Of Glycerin, fluroide, artificial coloring, foaming agents. Disclaimer These statements have not been evaluated by the FDA. These products are not intended to diagnose, treat, cure, or prevent any disease.', 'Home & Living', 'Redmond', 13.2, 83, '"https://i5.walmartimages.com/seo/Redmond-Earth-Paste-Natural-Toothpaste-Unsweetend-Spearmint-4-Oz_29514b72-86c1-415f-896a-91ad5df766e5.ec0cb6b137cf70fc889eafccf9f16e04.jpeg"', 5.0, 1, 16);
