INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1402, 'Cool Whip Extra Creamy Whipped Cream Topping, 8 oz Tub', 'Cool Whip Extra Creamy Whipped Topping is a one-of-a-kind dessert topping that adds sweet flavor and extra creamy texture to all your favorite desserts and recipes. With its unique and trusted formula, Cool Whip completes your dessert. Add a dollop of Cool Whip to strawberry shortcake, chocolate pie or banana pudding to take your favorite desserts to the next level. Cool Whip also makes a deliciously decadent fruit dip, or try using it to top off the perfect ice cream sundae. Place unopened 8 ounce tub in refrigerator for 4 hours to thaw. Do not stir. Keeps fresh in refrigerator 2 weeks. May be refrozen for longer storage.', 'Home & Living', 'Cool Whip', 1.98, 58, '"https://i5.walmartimages.com/seo/Cool-Whip-Extra-Creamy-Whipped-Cream-Topping-8-oz-Tub_2bfbd0d1-bc15-4400-9ae5-e07451cec671.ba6e666b9d13d6885daa885ba64ebc83.jpeg"', 0.0, 0, 41);
