INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1417, 'Organic Red Quinoa, 20 Pounds Non-GMO, Raw, Kosher, Vegan by Food to Live', 'Organic Red Quinoa is a seed from a plant called goosefoot which is not a member of a true grass family. Quinoa is much related to species like beets, tumbleweeds, and spinach. Quinoa is known for its high in nutrients and its nutty flavor and crunchy texture makes a tummy friendly food as it is also gluten-free which means that it can be easily enjoyed by individuals that have sensitivity in gluten. It is usually boiled and consumed as a breakfast porridge, side dish, added to a salad or as a thickening agent for soups and stews.', 'Home & Living', 'Food to Live', 73.0, 82, '"https://i5.walmartimages.com/seo/Organic-Red-Quinoa-20-Pounds-Non-GMO-Raw-Kosher-Vegan-by-Food-to-Live_7b674348-41b0-4ef6-960b-8fc6b8917067.945aee5f8ed50816ca299afc5f5d77cb.jpeg"', 0.0, 0, 26);
