INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1443, 'Unique Loom Rounded Trellis Frieze Rug Ivory/Gray 2'' x 10'' Runner Trellis Traditional Perfect For Bathroom Hallway Mud Room Laundry Room', 'Rounded trellis pattern ivory and gray rug runner Machine made medium pile; rectangular shaped Effortless cleaning; smudge resistant; does not shed Recommended for indoor use; made in Turkey Runner measures 2 feet wide by 10 feet long Product Features: Color(s): ivory and gray. Rounded trellis pattern rectangular rug runner. Machine made medium pile. Backing: yes. Recommended for indoor use. Easy-to-clean, stain resistant, and does not shed. Use a rug pad to reduce slipping and sliding. Rug pad sold separately Made in Turkey. Care instructions: Spot clean only. Regular vacuuming. Use a carpet cleaner but it should be dried immediately and evenly. In case of creases - roll the rug in the opposite direction, while applying pressure to the rug - take the edge, flip it where there is a crease, and slowly pull the rug back, while applying downward pressure on the crease. Dimensions: 2'' wide x 10'' long. Pile height: 0.33". Material(s): polypropylene. Backing: cotton', 'Home & Living', 'Unique Loom', 40.0, 81, '"https://i5.walmartimages.com/seo/Unique-Loom-Rounded-Trellis-Frieze-Rug-Ivory-Gray-2-x-10-Runner-Trellis-Traditional-Perfect-For-Bathroom-Hallway-Mud-Room-Laundry-Room_6eaa44e6-61f7-4f57-9cb9-3a1821bb378e.c0857d3aa3863f7f755a48d020257ebe.jpeg"', 0.0, 0, 19);
