, 55, '"https://i5.walmartimages.com/seo/Amay-800-TC-100-Organic-Cotton-RV-Short-Queen-Size-1Pc-Fitted-Sheet-60X75-Fits-Mattress-Upto-8-10-inches-Teal-Solid_32f61344-4466-4c9a-8c70-24639898282c.5236841ab05ccedbcd65da550b7ed38a.jpeg"', 0.0, 0, 5);
