INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1510, 'LA Linen Polyester Gingham Checkered 58 by 58-Inch Square Tablecloth, Lime and White', '100% Yarn Dyed 1" Checkered polyester Made in the USA Serged edge for a clean look. Stain and wrinkle resistance, bringing a time honored pattern to the new age. This Tablecloth is reversible! LA Linen exclusive gingham checkered pattern is a yarn dyed, 100% spun polyester fabric at 215 GSM. Making this a double sided fabric of highest quality and durability This Tablecloth can easily be machine washed and will also withstand Professional cleaning detergents. Cold Machine,Tumble Dry Low, Low Iron . LA Linen exclusive Size and care label to ensure the authenticity and quality of your item. The digital images we display have the most accurate color possible. However, due to differences in computer monitors, there may be variations in color between the actual product and your screen', 'Home & Living', 'LA Linen', 24.1, 71, '"https://i5.walmartimages.com/seo/LA-Linen-Polyester-Gingham-Checkered-58-by-58-Inch-Square-Tablecloth-Lime-and-White_03efcd26-9789-4487-bf55-13abb5045b26.cdcca41b3efd2f986ff7d418c8e36676.jpeg"', 0.0, 0, 36);
