INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1517, 'Parodontax Active Gum Repair Whitening Toothpaste - Mint Flavor, 3.4 oz', 'Gum Protection and Whitening Toothpaste Parodontax Active Gum Repair Whitening is a daily whitening toothpaste that helps reduce bleeding gums while restoring your teeth to their natural whiteness with twice daily brushing. Formulated with stannous fluoride, this antigingivitis toothpaste is three times more effective than a sodium monofluorophosphate toothpaste at removing plaque, the main cause of bleeding gums. This anticavity and antigingivitis toothpaste kills plaque bacteria at the gum line to help reverse early signs of gum damage. As a fluoride toothpaste, Parodontax toothpaste also helps repair weakened enamel and helps whiten teeth. Brush with this gum toothpaste twice daily to help reverse signs of early gum damage. Leave bleeding gums behind. (1) than a sodium monofluorophosphate toothpaste', 'Home & Living', 'Parodontax', 11.0, 50, '"https://i5.walmartimages.com/seo/Parodontax-Active-Gum-Repair-Whitening-Toothpaste-Mint-Flavor-3-4-oz_8e77aa8a-1045-49a6-9c89-952e892df889.4121f33c2863341ca7d5a694b78e4b1c.jpeg"', 0.0, 0, 16);
