INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1556, 'Lux Decor Collection Fitted Sheet - Ultra Soft Brushed Microfiber Full Size Fitted Sheet, Upto 16 Inches Deep Pocket Fitted Sheet Only, White', 'PREMIUM QUALITY: Elevate your full-size mattress with our full fitted sheet. Crafted from High GSM brushed microfiber, it resists fade, shrinkage, and wrinkles, staying free from pilling even after regular use. ELASTIC DEEP POCKETS: Our full fitted sheet perfectly fits mattresses up to 16 inches deep, featuring all-around elastic for easy installation and removal. The non-slip lightweight fabric ensures a snug fit for ultimate comfort. SOFT &amp; BREATHABLE: Enjoy a restful night''s sleep with our cozy full-size fitted sheet. Its breathable design keeps you warm in winter and cool in summer. VERSATILE &amp; LUXURIOUS: Lux Decor Collection offers exceptionally stitched full fitted sheets (54 x 75 inches) in various colors, adding a luxurious touch to your bedroom decor. EASY CLEANING: Machine wash cold on a gentle cycle. Tumble dry low and avoid bleach. Contact us for any questions; customer satisfaction is our top priority.', 'Home & Living', 'LDC Lux Decor Collection', 15.0, 62, '"https://i5.walmartimages.com/seo/Lux-Decor-Collection-Fitted-Sheet-Ultra-Soft-Brushed-Microfiber-Full-Size-Fitted-Sheet-Upto-16-Inches-Deep-Pocket-Fitted-Sheet-Only-White_d313e427-7403-4cc5-a41f-167e5583f994.d589716c4324c497783201170597a6a4.jpeg"', 0.0, 0, 16);
