INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1587, 'Instant Pho Vegetarian Pack of 4 Bowls / Authentic Vietnamese Soup / Pholicious Brand - New', 'Single serve bowls of PhoLicious Instant Vietnamese Vegetarian Pho. New. Shelf Stable 1 Year. No other bowl includes the complete ingredients, from spices to condiments, to make a 100% authentic Vietnamese meal in minutes! Take your taste buds on a trip to Vietnam with PhoLicious! MAMA THU &amp; PAPA LE fled Vietnam on a small boat with their daughter, Anh. After being attacked by pirates &amp; saved by Malaysian fishermen, they were taken to the Philippians &amp; arrived in the United States as refugees in the late 1980''s. Years later, Mama Thu &amp; Papa Le invested everything they had into opening their own restaurant in St. Louis, utilizing generations of authentic family recipes. Fast forward to the 2020 pandemic when all of the pho restaurants were shut down, Anh joined forces with Mama Thu in order to create an authentic Pho ready in minutes! We are excited to share PhoLicious with the world, and bring authentic Pho from our home to yours! 3.6 ounces per bowl dry weight.', 'Home & Living', 'PhoLicious', 27.0, 67, '"https://i5.walmartimages.com/seo/Instant-Pho-Vegetarian-Pack-of-4-Bowls-Authentic-Vietnamese-Soup-Pholicious-Brand-New_5084b941-02f8-43df-9c85-3850f609cbaa.8f8f9601af730468dc8a9fd540510717.jpeg"', 0.0, 0, 16);
