INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1590, 'Anray Home Luxurious Bath Towel Set 8 Piece - 600 GSM 100% microfiber Highly Absorbent and Quick Dry Extra Large Bath Towel - Soft Hotel Quality Towel (35 x 70 Inches)', '8 Pcs Soft Plush Bath Towel Set: Home collections kitchen bathroom towel set includes 2 towels(16"*31"), 2 bath towels(35"*70") and 4 washclothes(13"*13"). They''re also available in a variety of colors to coordinate with different decor styles. Premium Water Absorption: Our soft bath towel set collection is of 600 GSM which has high water absorption.The towel can absorb 3 times its own weight of water. Soft and Fluffy: The plush bath towels give you a comfy experience after a bath. Superior microfiber ensures optimum softness. Durable &amp; Reliable: Bath towel set is made of 100% microfiber. Anti-fading, anti-static, wrinkle and shrink resistant, which ensures durability and reliability. Excellent Appearance: The bath towels have bright colors and beautiful patterns. They can also be given as gifts to friends and family.', 'Home & Living', 'Anray Home', 25.0, 44, '"https://i5.walmartimages.com/seo/Anray-Home-Luxurious-Bath-Towel-Set-8-Piece-600-GSM-100-microfiber-Highly-Absorbent-Quick-Dry-Extra-Large-Soft-Hotel-Quality-35-x-70-Inches_db09f102-7448-49df-872d-8418ac5082dc.a9c2f83ef348dafa547186c04991a283.jpeg"', 0.0, 0, 18);
INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1591, 'Jockey Men''s Sport Stability Pouch Microfiber 6" Boxer Brief', 'Love support but can''t stand the squeeze? Experience total support without compression in Jockey Sport Stability Pouch Microfiber Boxer Brief men''s underwear. Crafted with breathable quick-dry mesh and eco-friendly recycled polyester, our supportive U-pouch is engineered with a contoured fit that keeps you gently held in place while you jog or train. Enhanced with Staycool+ technology for moisture-wicking comfort that helps you keep your cool, this pair offers a compression-free fit and secure support without restrictions. Stay focused and minimize bounce with a comfortable fit that keeps everything in place.', 'Home & Living', 'Jockey', 9.99, 58, '"https://i5.walmartimages.com/seo/Jockey-Men-s-Sport-Stability-Pouch-Microfiber-6-Boxer-Brief_8999ffbb-ea04-4c20-ae43-ee637e4d0dd1.c8d55a00f84941506c369a82a7116ff3.jpeg"', 0.0, 0, 48);
INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1592, 'Eclipse Dayton Solid Blackout Rod Pocket Energy-Efficient Curtain Panel, Chocolate, 42"x63"', 'Experience the darkness, silence, and beauty of energy efficient Eclipse curtains. Eclipse blackout panels have been laboratory-tested to block out over 99 percent of intrusive light, unwanted noise and can help you save on home heating and cooling costs. Eclipse curtains offer a unique blend of fashion and function for any home dcor. The innovative foam-backing is applied to the fabric and allows you to enjoy all of the light-blocking, noise reducing and energy saving benefits, while providing the same fashionable style and elegance of naturally flowing curtains. Made in China.', 'Home & Living', 'Eclipse', 19.0, 62, '"https://i5.walmartimages.com/seo/Eclipse-Dayton-Solid-Blackout-Rod-Pocket-Energy-Efficient-Curtain-Panel-Chocolate-42-x63_4f6e4fc0-d427-4ee8-bedc-5dec918672b9.0fe5258f4306def3d455f68387a77236.jpeg"', 3.0, 1, 6);
