INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1640, 'Liberty Blues Men''s Big & Tall Longer-Length Shrink-Less Piqu Polo', 'Liberty Blues Men''s Big &amp; Tall Longer-Length Shrink-Less Piqu&eacute; Polo .This&nbsp;Liberty Blues Longer-Length Piqu&eacute; Polo has you covered. It''s 4&quot; longer than our standard polo ensuring&nbsp;for a gap-free fit. In our trademarked&nbsp;Shrink-Less design for longer-lasting wear too! Relaxed fit4&quot; longer lengthLeft chest pocketStraight hem with side ventsItch-free tagless label100% cottonMachine wash; imported Big length approx. 36&quot;Tall length approx. 38&quot; Order Big sizes if you are 6''1&quot; or shorter. Order Tall sizes if you are 6''2&quot; or taller.. About the brand: Liberty Blues delivers uncomplicated, quality clothing for the big &amp; tall guy. Our denim has stretch built in giving you that classic look with extra comfort and mobility. Our shirts and sweaters are made from premium fabrics like soft brushed flannel or hardy knits. Getting dressed is easy with tried-and-true style and expertise.', 'Home & Living', 'Liberty Blues', 31.9, 71, '"https://i5.walmartimages.com/seo/Liberty-Blues-Men-s-Big-Tall-Longer-Length-Shrink-Less-Piqu-Polo_c539a2cf-3723-431e-95c7-e0837b3f9a1e.08dc895f91c5e912fc1fd55021456b48.jpeg"', 0.0, 0, 26);
