INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1658, 'Men''s Home Alone Merry Christmas Ugly Sweater Graphic Tee Navy Blue Heather 2X Large', 'Enjoy comfort and fashion at the same time with this unique festive men''s graphic tee design from Home Alone. Strut your stuff with this stylish new Christmas men''s t-shirt that is perfect for the holidays! Featuring the text: "Merry Christmas Ya Filthy Animal," in an ugly sweater style across the front. Find the perfect fit for you! Check out size charts for more information. Made from the highest quality materials on first-class digital direct-to-garment printers. *This item is made to order; please consider this when ordering multiple sizes.* Printed in the U.S.A. with safe water-based inks. Easy care; machine wash cold inside out with similar colors, tumble dry low (hang dry for best results). Officially licensed apparel. Designed by and exclusive collaboration with top brands &amp; world-class artists.', 'Kitchen & Appliances', 'Home Alone', 16.0, 18, '"https://i5.walmartimages.com/seo/Men-s-Home-Alone-Merry-Christmas-Ugly-Sweater-Graphic-Tee-Navy-Blue-Heather-2X-Large_461f53c8-c796-4f4f-9bbe-924e4e19aa12.dbdc89187f6a2171567735666d530fc3.jpeg"', 3.0, 1, 37);
