INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1671, 'California Design Den Queen Fitted Sheet Only, Softest 400 Thread Count 100% Cotton Sateen, Deep Pocket, All-Around Elastic, Side Indicators - Teal', 'Fitted Sheets Sold Separately (Not a Set) - KEY FEATURES: 100% cotton fitted sheet Luxury 400 thread count soft &amp; durable fabric Deep pockets &amp; fits mattresses 8 inches to 16 inches deep Best sheets with strong all-round elastic for snug, no pop-off fit Smart head &amp; foot tags for easy bed making experience Cooling &amp; breathable with smooth sateen weave Tested for shrinkage, pilling &amp; color-fastness Certified OEKO-TEX &amp; STANDARD-100 - Cooling fitted sheet perfect for all skin types including sensitive skin These queen size sheets are easy to machine wash &amp; dry INCLUDES ONE DEEP POCKET SNUG FITTED SHEET ONLY: Each queen size bottom sheet measures 60" W x 80" L that fits both low foam and tall mattresses that are 8-16" deep. Our fitted 100% cotton sheets are also available in King, Twin, Twin-XL, Full, Cal-King Sizes. Match it with our pillow cases, flat sheets, duvet covers and more. Our California Design Den cotton bed sheets are better than fake Egyptian cotton sheets and backed by a risk-free Lifetime Guarantee against defects in materials and craftsmanship.', 'Home & Living', 'California Design Den', 30.0, 60, '"https://i5.walmartimages.com/seo/California-Design-Den-Queen-Fitted-Sheet-Only-Softest-400-Thread-Count-100-Cotton-Sateen-Deep-Pocket-All-Around-Elastic-Side-Indicators-Teal_8772ad28-b83d-4efa-9cf7-553dd5891cd0.ed82bd622d80e636bcafbfac0dffff69.jpeg"', 0.0, 0, 9);
