INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1673, 'Dash Original Seasoning Blend, Salt free, 21 oz', 'Dash Salt-Free Original Seasoning Blend 21 oz bottle helps you make cooking delicious again. This salt free seasoning blend is an all-purpose mix of herbs and spices that is easy to love and simple to pair with almost anything. The flavor of this no salt seasoning blend is created by mixing over 14 different spices together, including cayenne pepper, cumin, basil, and garlic. Dash Salt Free Original Seasoning is kosher so you can enjoy a delicious meal without skipping out on taste. This Dash salt free seasoning is perfect for bringing instant flavor and a little bit of spice to your favorite meats, vegetables, sauces, and more. Smarter cooking is simple with this Dash seasoning mix. Dash salt-free seasoning mix makes a flavorful statement.', 'Home & Living', 'Dash', 13.1, 21, '"https://i5.walmartimages.com/seo/Dash-Original-Seasoning-Blend-Salt-free-21-oz_28115456-d416-4be4-9b81-175844b5cb75.42ebdff81053a3c2f4c3ab0270514de2.jpeg"', 3.0, 1, 5);
