INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1739, 'Purina ONE High Protein, Healthy Weight Dry Cat Food, +Plus Ideal Weight With Turkey, 7 lb. Bag', 'Help your feline maintain her healthiest weight with Purina ONE +Plus Ideal Weight High Protein, Natural With Added Vitamins, Minerals and Nutrients dry cat food. Crafted by a veterinarian-recommended brand, this Purina ONE cat kibble combines the power of nature and research to help spayed and neutered cats maintain an ideal weight. We craft this weight management cat food with L-carnitine and a SmartBlend of high-quality ingredients to help your cat burn fat and maintain a healthy weight. With 0 percent fillers, every ingredient has a purpose in her dish. The high protein cat food recipe starts with real turkey as the #1 ingredient and contains 42 percent protein to meet her protein requirements as a carnivore and help support her strong muscles, including her healthy heart. Plus, grains and accents of real vegetables come together in this Purina ONE natural cat food with added vitamins, minerals and nutrients to provide 100 percent complete and balanced nutrition your adult cat needs to thrive.', 'Pet Supplies', 'Purina ONE', 18.0, 32, '"https://i5.walmartimages.com/seo/Purina-ONE-High-Protein-Healthy-Weight-Dry-Cat-Food-Plus-Ideal-Weight-With-Turkey-7-lb-Bag_163aa5d1-345f-43cd-8ca8-12a0c4bbfe96.690da9645c7a32f0dd1eb538ae289a72.jpeg"', 0.0, 0, 47);
