INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1746, 'Revlon ColorStay Liquid Foundation Makeup, Matte Finish, Combination/Oily Skin, SPF 15, Vanilla, 1 fl oz.', 'Better skin by the day. Revlon ColorStay Longwear Makeup for Combination/Oily Skin with SPF15 is an oil-free, fragrance-free foundation that offers 24-hour wear and helps improve your skins appearance day after day. Skin-caring ingredients include antioxidant Vitamin E to help nourish and protect skin from pollutants, while earth-sourced multi-mineral powders control oil breakthrough all day long. This breathable, buildable makeup formula resists heat, sweat, and humidity round the clock. Transfer-resistant, waterproof, and mask-friendly. Available in 43 diverse shades for all skin. We got you covered.', 'Home & Living', 'Revlon', 12.5, 37, '"https://i5.walmartimages.com/seo/Revlon-ColorStay-Liquid-Foundation-Makeup-Matte-Finish-Combination-Oily-Skin-SPF-15-135-Vanilla-1-fl-oz_87f434bb-b072-4621-beaf-7a200342b1ee.505dc3c6803de0b72cf2f5bcd367d62c.jpeg"', 0.0, 0, 41);
