INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1818, 'HIG Light Weight Down Alternative Comforter Set, Twin, Plum, Reversible', 'No size shortage problem for the bed. Real Standard Size without tricking on the market. No Color Matching problem for different home decorations. Nice color matches in eight groups of colorways for more options of home decoration. And two color-matching Shams save your money &amp; time on finding matchable shams. No quality-worry problem. By using high-quality certified materials on fabric and filling, the comforter has greater longevity than your expectation. No annoying mess-up trouble after wash. By applying special treated high-quality fiberfill and sewing-stitching crafts, the shape keeps well even after many washes Not too hot, not too cold. Based on the medium weight, medium warmth rating that makes it great for use all year round. Twin set includes: 1 comforter(68"x92"),2 shams(20"x26") Queen set includes: 1 comforter (90"x92") and 2 shams (20"x26") King set includes: 1 comforter (104"x 92") and 2 shams (20"x36") Oversize King set includes: 1 comforter (116"x 95") and 2 shams (20"x36")', 'Home & Living', 'HIG', 36.0, 60, '"https://i5.walmartimages.com/seo/HIG-Light-Weight-Down-Alternative-Comforter-Set-Twin-Plum-Reversible_7f45c99d-3be8-4b9e-96ff-af6b5aee0732.7f1b280cfb79a72ae3d4c5815f89fdd5.jpeg"', 5.0, 1, 29);
