INSERT INTO product (id, name, description, category, brand, price, stock, main_image, rating, review_count, seller_id) VALUES (1833, 'Purina Beneful Incredibites Wet Dog Food for Small Adult Dogs, Real Beef, 3 oz. Cans (24 Pack)', 'Purina Beneful Incredibites for Small Dogs Wet Dog Food Real Beef, 3 oz Cans (24 Pack) Small breed dog food made with real beef and real vegetables and grains you can see formulated specifically for small dogs High protein dog food helps support strong muscles and contains no artificial colors, flavors or preservatives Small, tender bites are perfect for small mouths, and a flavorful gravy adds the finishing touch to this small adult dog food 100 percent complete and balanced small breed adult dog food includes 23 essential vitamins and minerals Purina Beneful IncrediBites for small dogs is perfectly portioned in 3 oz. servings and proudly produced in Purina-owned facilities Spoil your pet with Purina products. Reward yourself with points on every purchase. Download the myPurina app today', 'Home & Living', 'Beneful', 2.74, 100, '"https://i5.walmartimages.com/seo/Purina-Beneful-Incredibites-Wet-Dog-Food-for-Small-Adult-Dogs-Real-Beef-3-oz-Cans_2ced8239-7916-49bd-93cd-7fd70dc21e8d.6a83ee1486d3dce04e8880e8dbaf7e7a.jpeg"', 0.0, 0, 32);
